public boolean shouldResync(){
  lock.writeLock().lock();
  boolean resyncNeeded=false;
  try {
    this.syncingListeners.clear();
    ZonedDateTime now=ZonedDateTime.now();
    for (    ProcessorListener<T> listener : this.listeners) {
      if (listener.shouldResync(now)) {
        resyncNeeded=true;
        this.syncingListeners.add(listener);
        listener.determineNextResync(now);
      }
    }
  } catch (UnsupportedOperationException | IllegalArgumentException | ClassCastException | NullPointerException | ArithmeticException | DateTimeException e) {
    e.printStackTrace();
  } finally {
    lock.writeLock().unlock();
  }
  return resyncNeeded;
}
